110:    pub fn parse(allocator: std.mem.Allocator, reader: *thrift.CompactReader) !?Self {
176:                    const geo_type = try parseGeometryType(allocator, reader);
181:                    const geo_type = try parseGeographyType(allocator, reader);
469:fn parseGeometryType(allocator: std.mem.Allocator, reader: *thrift.CompactReader) !GeometryType {
486:fn parseGeographyType(allocator: std.mem.Allocator, reader: *thrift.CompactReader) !GeographyType {

1	//! Logical Types for Parquet
2	//!
3	//! Logical types provide semantic meaning to physical types.
4	//! For example, a TIMESTAMP is an INT64 with time semantics.
5	
6	const std = @import("std");
7	const safe = @import("../safe.zig");
8	const thrift = @import("../thrift/mod.zig");
9	
10	/// Edge interpolation algorithm for Geography logical type
11	/// Thrift enum EdgeInterpolationAlgorithm
12	pub const EdgeInterpolationAlgorithm = enum(u8) {
13	    spherical = 0,
14	    vincenty = 1,
15	    thomas = 2,
16	    andoyer = 3,
17	    karney = 4,
18	
19	    pub fn fromInt(value: i32) !EdgeInterpolationAlgorithm {
20	        return switch (value) {
21	            0 => .spherical,
22	            1 => .vincenty,
23	            2 => .thomas,
24	            3 => .andoyer,
25	            4 => .karney,
26	            else => error.InvalidEdgeInterpolationAlgorithm,
27	        };
28	    }
29	};
30	
31	/// Geometry logical type annotation (Thrift field 17 in LogicalType)
32	/// Geospatial features in WKB format with linear/planar edge interpolation
33	pub const GeometryType = struct {
34	    /// Coordinate Reference System identifier. Default is "OGC:CRS84"
35	    crs: ?[]const u8 = null,
36	};
37	
38	/// Geography logical type annotation (Thrift field 18 in LogicalType)
39	/// Geospatial features in WKB format with explicit edge interpolation algorithm
40	pub const GeographyType = struct {
41	    /// Coordinate Reference System identifier. Default is "OGC:CRS84"
42	    crs: ?[]const u8 = null,
43	    /// Edge interpolation algorithm. Default is spherical
44	    algorithm: ?EdgeInterpolationAlgorithm = null,
45	};
46	
47	/// Time units for TIMESTAMP and TIME logical types
48	pub const TimeUnit = enum {
49	    millis,
50	    micros,
51	    nanos,
52	
53	    pub fn thriftFieldId(self: TimeUnit) u8 {
54	        return switch (self) {
55	            .millis => 1,
56	            .micros => 2,
57	            .nanos => 3,
58	        };
59	    }
60	};
61	
62	/// Timestamp logical type - INT64 with time semantics
63	pub const TimestampType = struct {
64	    is_adjusted_to_utc: bool,
65	    unit: TimeUnit,
66	};
67	
68	/// Time logical type - INT32 (millis) or INT64 (micros/nanos)
69	pub const TimeType = struct {
70	    is_adjusted_to_utc: bool,
71	    unit: TimeUnit,
72	};
73	
74	/// Decimal logical type - requires precision and scale
75	/// Physical type: INT32 (precision <= 9), INT64 (precision <= 18), or FIXED_LEN_BYTE_ARRAY
76	pub const DecimalType = struct {
77	    precision: i32, // Total digits
78	    scale: i32, // Digits after decimal point
79	};
80	
81	/// Integer logical type - signed/unsigned with bit width
82	/// Physical type: INT32 (8/16/32 bit) or INT64 (64 bit)
83	pub const IntType = struct {
84	    bit_width: i8, // 8, 16, 32, or 64
85	    is_signed: bool,
86	};
87	
88	/// Logical type union - field 10 in SchemaElement
89	/// Per Parquet spec, this is a Thrift union with specific field IDs
90	pub const LogicalType = union(enum) {
91	    string, // Field 1: UTF8 string (empty struct)
92	    enum_, // Field 4: Enum (empty struct)
93	    decimal: DecimalType, // Field 5: Decimal with precision/scale
94	    date, // Field 6: Days since epoch (empty struct)
95	    time: TimeType, // Field 7
96	    timestamp: TimestampType, // Field 8
97	    // Field 9 is reserved for Interval
98	    int: IntType, // Field 10: Integer with bit width and signedness
99	    json, // Field 12: JSON (empty struct)
100	    bson, // Field 13: BSON (empty struct)
101	    uuid, // Field 14: UUID (empty struct)
102	    float16, // Field 15: IEEE 754 half-precision float (empty struct)
103	    // Field 16: VARIANT (not implemented)
104	    geometry: GeometryType, // Field 17: Geometry with WKB encoding
105	    geography: GeographyType, // Field 18: Geography with WKB encoding
106	
107	    const Self = @This();
108	
109	    /// Parse LogicalType from Thrift Compact Protocol
110	    pub fn parse(allocator: std.mem.Allocator, reader: *thrift.CompactReader) !?Self {
111	        const saved_field_id = reader.last_field_id;
112	        reader.resetFieldTracking();
113	
114	        var result: ?Self = null;
115	
116	        while (try reader.readFieldHeader()) |field| {
117	            switch (field.field_id) {
118	                1 => {
119	                    // STRING - empty struct
120	                    try reader.skip(.struct_);
121	                    result = .string;
122	                },
123	                4 => {
124	                    // ENUM - empty struct
125	                    try reader.skip(.struct_);
126	                    result = .enum_;
127	                },
128	                5 => {
129	                    // DECIMAL - DecimalType struct
130	                    const decimal_type = try parseDecimalType(reader);
131	                    result = .{ .decimal = decimal_type };
132	                },
133	                6 => {
134	                    // DATE - empty struct
135	                    try reader.skip(.struct_);
136	                    result = .date;
137	                },
138	                7 => {
139	                    // TIME - TimeType struct
140	                    const time_type = try parseTimeType(reader);
141	                    result = .{ .time = time_type };
142	                },
143	                8 => {
144	                    // TIMESTAMP - TimestampType struct
145	                    const ts_type = try parseTimestampType(reader);
146	                    result = .{ .timestamp = ts_type };
147	                },
148	                // Field 9 is reserved for Interval
149	                10 => {
150	                    // INT - IntType struct
151	                    const int_type = try parseIntType(reader);
152	                    result = .{ .int = int_type };
153	                },
154	                12 => {
155	                    // JSON - empty struct
156	                    try reader.skip(.struct_);
157	                    result = .json;
158	                },
159	                13 => {
160	                    // BSON - empty struct
161	                    try reader.skip(.struct_);
162	                    result = .bson;
163	                },
164	                14 => {
165	                    // UUID - empty struct
166	                    try reader.skip(.struct_);
167	                    result = .uuid;
168	                },
169	                15 => {
170	                    // FLOAT16 - empty struct
171	                    try reader.skip(.struct_);
172	                    result = .float16;
173	                },
174	                17 => {
175	                    // GEOMETRY - GeometryType struct
176	                    const geo_type = try parseGeometryType(allocator, reader);
177	                    result = .{ .geometry = geo_type };
178	                },
179	                18 => {
180	                    // GEOGRAPHY - GeographyType struct
181	                    const geo_type = try parseGeographyType(allocator, reader);
182	                    result = .{ .geography = geo_type };
183	                },
184	                else => try reader.skip(field.field_type),
185	            }
186	        }
187	
188	        reader.last_field_id = saved_field_id;
189	        return result;
190	    }
191	
192	    /// Serialize LogicalType to Thrift Compact Protocol
193	    pub fn serialize(self: *const Self, writer: *thrift.CompactWriter) !void {
194	        const saved = writer.saveFieldId();
195	        writer.resetFieldTracking();
196	
197	        switch (self.*) {
198	            .string => {
199	                // Field 1: STRING (empty struct)
200	                try writer.writeFieldHeader(1, .struct_);
201	                try writer.writeStructEnd();
202	            },
203	            .enum_ => {
204	                // Field 4: ENUM (empty struct)
205	                try writer.writeFieldHeader(4, .struct_);
206	                try writer.writeStructEnd();
207	            },
208	            .decimal => |d| {
209	                // Field 5: DECIMAL (DecimalType struct)
210	                try writer.writeFieldHeader(5, .struct_);
211	                try serializeDecimalType(&d, writer);
212	            },
213	            .date => {
214	                // Field 6: DATE (empty struct)
215	                try writer.writeFieldHeader(6, .struct_);
216	                try writer.writeStructEnd();
217	            },
218	            .time => |t| {
219	                // Field 7: TIME (TimeType struct)
220	                try writer.writeFieldHeader(7, .struct_);
221	                try serializeTimeType(&t, writer);
222	            },
