396	            1 => ts.is_adjusted_to_utc = field.field_type == .bool_true,
397	            2 => ts.unit = try parseTimeUnit(reader),
398	            else => try reader.skip(field.field_type),
399	        }
400	    }
401	
402	    reader.last_field_id = saved;
403	    return ts;
404	}
