13	    spherical = 0,
14	    vincenty = 1,
15	    thomas = 2,
16	    andoyer = 3,
17	    karney = 4,
18	
19	    pub fn fromInt(value: i32) !EdgeInterpolationAlgorithm {
20	        return switch (value) {
21	            0 => .spherical,
22	            1 => .vincenty,
23	            2 => .thomas,
24	            3 => .andoyer,
