288	    /// Get detailed string with parameters
289	    pub fn toDetailedString(self: Self, buf: []u8) []const u8 {
290	        return switch (self) {
291	            .string => "STRING",
292	            .enum_ => "ENUM",
293	            .decimal => |d| blk: {
294	                const result = std.fmt.bufPrint(buf, "DECIMAL({},{})", .{ d.precision, d.scale }) catch "DECIMAL(?)";
295	                break :blk result;
296	            },
297	            .date => "DATE",
298	            .time => |t| blk: {
299	                const unit_str = switch (t.unit) {
300	                    .millis => "MILLIS",
301	                    .micros => "MICROS",
302	                    .nanos => "NANOS",
303	                };
304	                const utc_str = if (t.is_adjusted_to_utc) "UTC" else "LOCAL";
305	                const result = std.fmt.bufPrint(buf, "TIME({s}, {s})", .{ utc_str, unit_str }) catch "TIME(?)";
306	                break :blk result;
307	            },
308	            .timestamp => |ts| blk: {
309	                const unit_str = switch (ts.unit) {
310	                    .millis => "MILLIS",
311	                    .micros => "MICROS",
312	                    .nanos => "NANOS",
313	                };
314	                const utc_str = if (ts.is_adjusted_to_utc) "UTC" else "LOCAL";
315	                const result = std.fmt.bufPrint(buf, "TIMESTAMP({s}, {s})", .{ utc_str, unit_str }) catch "TIMESTAMP(?)";
316	                break :blk result;
317	            },
318	            .int => |i| blk: {
319	                const signed_str = if (i.is_signed) "signed" else "unsigned";
320	                const result = std.fmt.bufPrint(buf, "INT({},{s})", .{ i.bit_width, signed_str }) catch "INT(?)";
321	                break :blk result;
322	            },
323	            .json => "JSON",
324	            .bson => "BSON",
325	            .uuid => "UUID",
326	            .float16 => "FLOAT16",
327	            .geometry => |g| blk: {
328	                if (g.crs) |crs| {
329	                    const result = std.fmt.bufPrint(buf, "GEOMETRY({s})", .{crs}) catch "GEOMETRY(?)";
330	                    break :blk result;
331	                } else {
332	                    break :blk "GEOMETRY";
333	                }
334	            },
335	            .geography => |g| blk: {
336	                const algo_str = if (g.algorithm) |a| switch (a) {
337	                    .spherical => "spherical",
338	                    .vincenty => "vincenty",
339	                    .thomas => "thomas",
340	                    .andoyer => "andoyer",
341	                    .karney => "karney",
342	                } else "spherical";
343	                if (g.crs) |crs| {
344	                    const result = std.fmt.bufPrint(buf, "GEOGRAPHY({s}, {s})", .{ crs, algo_str }) catch "GEOGRAPHY(?)";
345	                    break :blk result;
346	                } else {
347	                    const result = std.fmt.bufPrint(buf, "GEOGRAPHY({s})", .{algo_str}) catch "GEOGRAPHY(?)";
348	                    break :blk result;
349	                }
350	            },
351	        };
352	    }
353	};
