357	fn parseTimeUnit(reader: *thrift.CompactReader) !TimeUnit {
358	    const saved = reader.last_field_id;
359	    reader.resetFieldTracking();
360	
361	    var unit: TimeUnit = .millis; // default
362	
363	    while (try reader.readFieldHeader()) |field| {
364	        switch (field.field_id) {
365	            1 => {
366	                try reader.skip(.struct_); // MILLIS empty struct
367	                unit = .millis;
368	            },
369	            2 => {
370	                try reader.skip(.struct_); // MICROS empty struct
371	                unit = .micros;
372	            },
373	            3 => {
374	                try reader.skip(.struct_); // NANOS empty struct
375	                unit = .nanos;
376	            },
377	            else => try reader.skip(field.field_type),
378	        }
379	    }
380	
381	    reader.last_field_id = saved;
382	    return unit;
383	}
